def choose_move(observation):
    w, h = observation['grid_width'], observation['grid_height']
    px, py = observation['self_position']
    resources = observation.get('resources', [])
    obstacles = set(observation.get('obstacles', []))
    # Find closest resource
    if resources:
        target = min(resources, key=lambda r: abs(r['position'][0]-px)+abs(r['position'][1]-py))
        tx, ty = target['position']
    else:
        # no resources, stand still
        tx, ty = px, py
    dx = 0
    dy = 0
    if tx > px:
        dx = 1
    elif tx < px:
        dx = -1
    if ty > py:
        dy = 1
    elif ty < py:
        dy = -1
    # Check for obstacle or bounds
    new_x, new_y = px + dx, py + dy
    if (new_x, new_y) in obstacles or new_x < 0 or new_x >= w or new_y < 0 or new_y >= h:
        # try alternate directions
        if dx != 0:
            if (px, py+1) not in obstacles and 0 <= py+1 < h:
                dy = 1
            elif (px, py-1) not in obstacles and 0 <= py-1 >= 0:
                dy = -1
            else:
                dx, dy = 0, 0
        elif dy != 0:
            if (px+1, py) not in obstacles and 0 <= px+1 < w:
                dx = 1
            elif (px-1, py) not in obstacles and 0 <= px-1 >=0:
                dx = -1
            else:
                dx, dy = 0, 0
    return [dx, dy]
